@if ($status === 'Wawancara Berlangsung')
<script>
const audioConfig = { upload: @json(route('dokter.interview.audio.upload', $kunjungan)), status: @json(route('dokter.interview.audio.status', $kunjungan)), retry: @json(route('dokter.interview.audio.retry', $kunjungan)), transcript: @json(route('dokter.interview.transcript.update', $kunjungan)), finish: @json(route('dokter.interview.finish', $kunjungan)), maxSeconds: @json(config('medscribe.audio.max_duration_seconds')), maxBytes: @json(config('medscribe.audio.max_size_kb') * 1024) };
const csrf = document.querySelector('meta[name="csrf-token"]')?.content || @json(csrf_token());
let recorder, chunks = [], blob = null, timer, startedAt, segments = @json($segments), speakerMap = @json($wawancara->speaker_map ?? []);
const state = (text, cls = 'bg-slate-100 text-slate-600') => { const el = document.getElementById('recording-state'); el.textContent = text; el.className = 'text-[10px] font-bold rounded-lg px-2 py-1 ' + cls; };
const message = (text, error = false) => { const el = document.getElementById('recording-message'); el.textContent = text; el.className = 'text-xs mt-3 ' + (error ? 'text-rose-600' : 'text-slate-500'); };
function renderTranscript() { const root = document.getElementById('transcript-editor'); root.innerHTML = ''; segments.forEach((s, i) => { const row = document.createElement('div'); row.className = 'rounded-xl border border-slate-200 p-3'; row.innerHTML = `<div class="flex justify-between text-[11px] text-slate-400"><span>${Number(s.startTime).toFixed(1)}s - ${Number(s.endTime).toFixed(1)}s</span><span>${s.reviewStatus === 'ambiguous' ? 'Perlu diperiksa' : 'Tersimpan'}</span></div><textarea data-index="${i}" rows="2" class="transcript-text mt-2 w-full rounded-lg border border-slate-200 p-2 text-sm">${String(s.text || '').replaceAll('&','&amp;').replaceAll('<','&lt;')}</textarea><div class="grid grid-cols-2 gap-2 mt-2"><select data-speaker="${i}" class="speaker-role rounded-lg border border-slate-200 p-2 text-xs"><option value="unknown">Pembicara tidak dikenal</option><option value="doctor" ${s.speakerRole === 'doctor' ? 'selected' : ''}>Dokter</option><option value="patient" ${s.speakerRole === 'patient' ? 'selected' : ''}>Pasien</option></select><select data-status="${i}" class="review-status rounded-lg border border-slate-200 p-2 text-xs"><option value="confirmed" ${s.reviewStatus === 'confirmed' ? 'selected' : ''}>Terkonfirmasi</option><option value="ambiguous" ${s.reviewStatus === 'ambiguous' ? 'selected' : ''}>Ambigu</option><option value="edited" ${s.reviewStatus === 'edited' ? 'selected' : ''}>Diedit</option></select></div>`; root.appendChild(row); }); document.getElementById('save-transcript').classList.toggle('hidden', !segments.length); }
function syncSegments() { document.querySelectorAll('.transcript-text').forEach(el => { segments[el.dataset.index].text = el.value; segments[el.dataset.index].reviewStatus = 'edited'; }); document.querySelectorAll('[data-speaker]').forEach(el => { segments[el.dataset.speaker].speakerRole = el.value; }); document.querySelectorAll('[data-status]').forEach(el => { segments[el.dataset.status].reviewStatus = el.value; }); speakerMap = {}; segments.forEach(s => { if (s.speakerId) speakerMap[s.speakerId] = s.speakerRole; }); }
async function poll() { const res = await fetch(audioConfig.status, { headers: { Accept: 'application/json' } }); const data = await res.json(); document.getElementById('processing-state').textContent = (data.status || 'unknown').toUpperCase(); if (data.segments?.length) { segments = data.segments; renderTranscript(); } if (data.status === 'completed') { message(data.error ? `Transkripsi selesai; diarization perlu disiapkan: ${data.error}` : 'Pemrosesan lokal selesai. Tinjau speaker dan teks sebelum membuat SOAP.'); return; } if (data.status === 'failed') { message(data.error || 'Pemrosesan gagal.', true); state('GAGAL', 'bg-rose-50 text-rose-700'); document.getElementById('retry-process').hidden = false; return; } if (data.status) setTimeout(poll, 2500); }
document.getElementById('record-button').onclick = async () => { if (!navigator.mediaDevices?.getUserMedia || !window.MediaRecorder) return message('Browser tidak mendukung perekaman audio.', true); try { const stream = await navigator.mediaDevices.getUserMedia({ audio: true }); recorder = new MediaRecorder(stream); chunks = []; recorder.ondataavailable = e => e.data.size && chunks.push(e.data); recorder.onstop = () => { stream.getTracks().forEach(t => t.stop()); blob = new Blob(chunks, { type: recorder.mimeType || 'audio/webm' }); document.getElementById('recording-size').textContent = `${(blob.size / 1024 / 1024).toFixed(2)} MB`; document.getElementById('process-button').disabled = !blob.size; document.getElementById('retry-recording').hidden = false; state('SIAP DIPROSES'); message('Audio tersedia secara lokal.'); }; recorder.start(); startedAt = Date.now(); timer = setInterval(() => { const seconds = Math.floor((Date.now() - startedAt) / 1000); document.getElementById('recording-duration').textContent = `${String(Math.floor(seconds / 60)).padStart(2,'0')}:${String(seconds % 60).padStart(2,'0')}`; if (seconds >= audioConfig.maxSeconds) document.getElementById('stop-button').click(); }, 500); document.getElementById('record-button').disabled = true; document.getElementById('stop-button').disabled = false; state('MEREKAM', 'bg-rose-50 text-rose-700'); message('Rekaman aktif.'); } catch (e) { message('Izin mikrofon ditolak atau perangkat tidak tersedia.', true); } };
document.getElementById('stop-button').onclick = () => { if (recorder?.state === 'recording') recorder.stop(); clearInterval(timer); document.getElementById('record-button').disabled = false; document.getElementById('stop-button').disabled = true; };
document.getElementById('retry-recording').onclick = () => { if (confirm('Hapus rekaman lokal saat ini dan mulai ulang?')) { blob = null; chunks = []; document.getElementById('recording-size').textContent = ''; document.getElementById('process-button').disabled = true; state('SIAP'); message('Rekaman sebelumnya dihapus dari halaman.'); } };
document.getElementById('process-button').onclick = async () => { if (!blob) return; if (blob.size > audioConfig.maxBytes) return message('Ukuran audio melebihi batas konfigurasi.', true); const form = new FormData(); form.append('audio', blob, `interview-${Date.now()}.webm`); state('MENGUNGGAH', 'bg-sky-50 text-sky-700'); message('Mengirim audio ke backend lokal untuk diproses.'); const res = await fetch(audioConfig.upload, { method: 'POST', headers: { 'X-CSRF-TOKEN': csrf, Accept: 'application/json' }, body: form }); if (!res.ok) { const data = await res.json().catch(() => ({})); return message(data.message || 'Upload audio gagal.', true); } state('DIPROSES', 'bg-sky-50 text-sky-700'); document.getElementById('process-button').disabled = true; poll(); };
document.getElementById('retry-process').onclick = async () => { const res = await fetch(audioConfig.retry, { method: 'POST', headers: { 'X-CSRF-TOKEN': csrf, Accept: 'application/json' } }); if (res.ok) { document.getElementById('retry-process').hidden = true; state('DIPROSES', 'bg-sky-50 text-sky-700'); poll(); } else message('Pengulangan pemrosesan gagal.', true); };
document.getElementById('save-transcript').onclick = async () => { syncSegments(); const res = await fetch(audioConfig.transcript, { method: 'PUT', headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': csrf, Accept: 'application/json' }, body: JSON.stringify({ segments, speakerMap }) }); message(res.ok ? 'Koreksi transkrip tersimpan.' : 'Koreksi transkrip gagal disimpan.', !res.ok); if (res.ok) document.getElementById('soap-link').classList.remove('hidden'); };
renderTranscript();
document.getElementById('finish-button').onclick = () => { if (!confirm('Akhiri sesi dan lanjutkan ke review SOAP?')) return; const form = document.getElementById('interview-form'); form.action = audioConfig.finish; form.querySelector('input[name="_method"]')?.remove(); form.submit(); };
</script>
@endif
